def transform(grid):
    """Recolor every monochromatic row and column with 2."""
    out = [row[:] for row in grid]
    height = len(grid)
    width = len(grid[0])
    for r, row in enumerate(grid):
        if all(value == row[0] for value in row):
            out[r] = [2] * width
    for c in range(width):
        if all(grid[r][c] == grid[0][c] for r in range(height)):
            for r in range(height):
                out[r][c] = 2
    return out
